#!/usr/bin/env bash
# Generate the script install route from this extension's own release and update scripts.
#
# The route installs into public (fixed for v0), records its version in a marker table, and never
# needs a control file or CREATE EXTENSION. Generated files are committed under scripts/sql/ and
# attached to the matching GitHub release.
set -euo pipefail
cd "$(dirname "$0")/.."

version=$(sed -n "s/^default_version *= *'\(.*\)'/\1/p" pg_limit_runway.control)
release="pg_limit_runway--${version}.sql"
out=scripts/sql
mkdir -p "$out"

# Install: the release SQL with the CREATE EXTENSION guard and config-dump registration removed.
{
    printf '%s\n' '-- Generated by scripts/generate-script-route.sh. Do not edit by hand.'
    printf '%s\n' '-- The alternative install route; CREATE EXTENSION remains the default.'
    printf '%s\n' '\set ON_ERROR_STOP on'
    printf '%s\n' 'SET client_min_messages = warning;'
    printf '%s\n' 'SET check_function_bodies = off;'
    printf '%s\n' 'BEGIN;'
    cat <<'SQL'
DO $guard$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_limit_runway') THEN
        RAISE EXCEPTION 'pg_limit_runway is installed with CREATE EXTENSION; use ALTER EXTENSION, not the script route';
    END IF;
    IF to_regclass('public.limit_runway_script_install') IS NOT NULL THEN
        RAISE EXCEPTION 'the script route is already installed; use scripts/sql/migrate.sql';
    END IF;
END
$guard$;

CREATE TABLE public.limit_runway_script_install (
    version        text PRIMARY KEY,
    installed_at   timestamptz NOT NULL DEFAULT now(),
    route          text NOT NULL DEFAULT 'script',
    previous_version text
);
SQL
    sed -e '/^\\echo Use "CREATE EXTENSION/d' \
        -e '/pg_extension_config_dump(/d' \
        -e 's/@extschema@/public/g' \
        "$release"
    printf '\nINSERT INTO public.limit_runway_script_install (version) VALUES (%s);\n' "'$version'"
    printf '%s\n' 'COMMIT;'
} > "$out/install.sql"

# Uninstall: dependency order, no CASCADE, the schema stays.
cat > "$out/uninstall.sql" <<'SQL'
-- Generated by scripts/generate-script-route.sh. Do not edit by hand.
\set ON_ERROR_STOP on
SET client_min_messages = warning;
BEGIN;
DO $guard$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_limit_runway') THEN
        RAISE EXCEPTION 'pg_limit_runway is installed with CREATE EXTENSION; use DROP EXTENSION';
    END IF;
    IF to_regclass('public.limit_runway_script_install') IS NULL THEN
        RAISE EXCEPTION 'the script route is not installed in this database';
    END IF;
END
$guard$;

DROP VIEW IF EXISTS public.limit_runway;
DROP FUNCTION IF EXISTS public.limit_runway_text(numeric, interval);
DROP FUNCTION IF EXISTS public.limit_runway_command(numeric);
DROP FUNCTION IF EXISTS public.limit_runway_command_row(integer, text, text, timestamptz, timestamptz, numeric);
DROP FUNCTION IF EXISTS public.limit_runway_findings(numeric, interval);
DROP FUNCTION IF EXISTS public.limit_runway_unwatched();
DROP FUNCTION IF EXISTS public.limit_runway_rate(text, text);
DROP FUNCTION IF EXISTS public.limit_runway_projection(text, text);
DROP FUNCTION IF EXISTS public.limit_runway_project(text, text, text);
DROP FUNCTION IF EXISTS public.limit_runway_sequences();
DROP FUNCTION IF EXISTS public.limit_runway_sample(timestamptz);
DROP FUNCTION IF EXISTS public.limit_runway_prune(interval);
DROP FUNCTION IF EXISTS public.limit_runway_notify(text, interval, numeric);
DROP FUNCTION IF EXISTS public.limit_runway_notify_resolved(text, interval, numeric);
DROP FUNCTION IF EXISTS public.limit_runway_urgency(integer, timestamptz, numeric, interval);
DROP TABLE IF EXISTS public.limit_runway_history;
DROP TABLE IF EXISTS public.limit_runway_alert;
DROP TABLE public.limit_runway_script_install;
COMMIT;
SQL

# Per-step migrations, with the same substitutions as the install file.
for f in pg_limit_runway--*--*.sql; do
    base=${f#pg_limit_runway--}
    base=${base%.sql}
    {
        printf '%s\n' '-- Generated by scripts/generate-script-route.sh. Do not edit by hand.'
        sed -e '/^\\echo Use "ALTER EXTENSION/d' -e 's/@extschema@/public/g' "$f"
    } > "$out/migrate-${base}.sql"
done

# One entry point. It reads the marker and includes the needed steps in order.
{
    printf '%s\n' '-- Generated by scripts/generate-script-route.sh. Do not edit by hand.'
    printf '%s\n' '\set ON_ERROR_STOP on'
    printf '%s\n' 'DO $$ BEGIN IF to_regclass('\''public.limit_runway_script_install'\'') IS NULL THEN RAISE EXCEPTION '\''the script route is not installed'\''; END IF; END $$;'
    starts="0.1 0.2 0.2.1 0.2.2 0.3.0 0.4.0 0.4.1 0.5.0 0.5.1 0.5.2 0.6.0"
    printf '%s\n' 'SELECT version AS installed_version FROM public.limit_runway_script_install \gset'
    # Boolean psql variables, one per known start; \if only accepts a boolean value, not a SQL comparison.
    printf '%s\n' "SELECT version = '$version' AS v_current"
    for start in $starts; do
        printf '%s\n' ", version = '$start' AS v_$(echo "$start" | tr . _)"
    done
    printf '%s\n' 'FROM public.limit_runway_script_install \gset'
    printf '%s\n' 'BEGIN;'
    printf '%s\n' '\if :v_current'
    printf '%s\n' "\echo 'Already at $version; nothing to do.'"
    printf '%s\n' '\else'
    for start in $starts; do
        printf '%s\n' "\if :v_$(echo "$start" | tr . _)"
        cur=$start
        while [ "$cur" != "$version" ]; do
            next=$(ls pg_limit_runway--"$cur"--*.sql 2>/dev/null | head -1 | sed -e 's/.*--//' -e 's/\.sql//')
            [ -n "$next" ] || break
            printf '%s\n' "\ir migrate-${cur}--${next}.sql"
            cur=$next
        done
        printf '%s\n' '\endif'
    done
    printf '%s\n' '\endif'
    printf '%s\n' "UPDATE public.limit_runway_script_install SET previous_version = version, version = '$version';"
    printf '%s\n' 'COMMIT;'
} > "$out/migrate.sql"

(cd "$out" && sha256sum install.sql uninstall.sql migrate.sql migrate-*.sql > SHA256SUMS)

echo "generated $out/install.sql, uninstall.sql, migrate.sql and per-step files for $version"
